export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const pathname = url.pathname;

    if (pathname === '/' || pathname === '/home') return new Response(renderHomepage(), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
    if (pathname === '/login') return new Response(renderLogin(), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
    if (pathname === '/register') return new Response(renderRegister(), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
    if (pathname === '/dashboard') return new Response(renderDashboard(), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
    if (pathname === '/courses') return new Response(renderCourses(), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
    if (pathname === '/free-resources') return new Response(renderFreeResources(), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
    if (pathname === '/checkout') return new Response(renderCheckout(url), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
    if (pathname === '/admin') return new Response(renderAdmin(), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });
    if (pathname === '/portal' || pathname === '/client-portal') return new Response(renderClientPortal(), { headers: { 'Content-Type': 'text/html; charset=UTF-8' } });

    return new Response('404 - Page not found', { status: 404 });
  }
};

